(() => {
  const s = $('Gmail Trigger').item.json.From || '';
  const inBrackets = s.match(/<([^>]+)>/);
  const candidate = inBrackets ? inBrackets[1] : s;
  const m = candidate.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return m ? m[0] : '';
})()
}}

={{
(() => {
  const s = $('Gmail Trigger').item.json.snippet || '';
  // Decode a few entities
  const dec = s.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');
  // Cut off quoted thread markers like: "On Sat, ... wrote:"
  const i = dec.search(/\sOn .*wrote:/i);
  const head = i !== -1 ? dec.slice(0, i) : dec;
  // Trim and collapse spaces
  return head.replace(/\s+/g,' ').trim();
})()
}}

