actionFields.replaceText:
={{ 
  (() => {
    const d = $('Basic LLM Chain1').item.json;
    const raw = Array.isArray(d.services) ? d.services : [];
    const normalized = raw.map(s => {
      if (!s) return '';
      if (typeof s === 'string') return s.trim();
      if (typeof s === 'object') {
        const name = String(s.name || s.title || s.service || '').trim();
        const desc = String(s.description || s.desc || '').trim();
        return desc ? `${name} — ${desc}` : name;
      }
      return String(s).trim();
    }).filter(Boolean);
    return normalized.length ? normalized.map(s => `- ${s}`).join('\n') : '';
  })()
}}

={{ 
  (() => {
    const d = $('Basic LLM Chain1').item.json;
    const items = Array.isArray(d.pricing_items) ? d.pricing_items : [];
    const cur = d.currency || 'EGP';
    const fmt = new Intl.NumberFormat('en-EG', { style: 'currency', currency: cur, minimumFractionDigits: 0, maximumFractionDigits: 2 });
    return items
      .filter(i => i && i.label)
      .map(i => `- ${i.label}: ${fmt.format(Number(i.amount) || 0)}`)
      .join('\n');
  })()
}}

